\documentclass[12pt]{article}
\usepackage[utf8]{inputenc}
\usepackage[T1]{fontenc}
\usepackage{hyperref}
\title{Faroese Language Resources for K-12 Curriculum Development}
\author{Compiled by Claude Sonnet 5.5 (claude-sonnet-5-5) for Andr\'as Kornai}
\date{}
\begin{document}
\maketitle

\section{Introduction}
Faroese (ISO 639-3 \texttt{fao}, Glottocode faro1244) is the national language of the Faroe Islands and the language of instruction in Faroese schools. Search results indicate a functioning native-language school system, a dedicated educational publisher (N\'am), a national dictionary portal, and a Bible translation. The main gap reported is materials for Faroese as a second language.

\section{Primary Educational Resources}
\begin{itemize}
\item \emph{Finka -- f{\o}royskt til annan flokk}, a second-grade Faroese textbook by Marianna Skar\dh enni Poulsen; it won gold at the 2020 Best European Learning Materials Awards. \url{https://kvf.fo/greinar/2020/10/14/faroese-schoolbook-wins-major-european-award}
\item Wikipedia, ``Education in the Faroe Islands'': structure of the school system. \url{https://en.wikipedia.org/wiki/Education_in_the_Faroe_Islands}
\item N\'am is described in search results as the only educational publisher in the Faroes, producing mainly primary and lower-secondary materials (see the kvf.fo article above).
\end{itemize}

\section{Linguistic and Reference Materials}
\begin{itemize}
\item Sprotin online dictionaries (Faroese with Danish, English, German, Spanish and Chinese; free under a government agreement). \url{https://www.studyinfaroeislands.fo/life-in-the-faroes/learn-the-language/online-dictionary-sprotin}
\item Faroese Spelling Dictionary (University of the Faroe Islands). \url{https://mtd.setur.fo/en/resource/stavsetingarordabokin/}
\item Faroese Language Committee-related overview from the Faroese government site. \url{https://tvk.fo/en/living/language-culture/faroese-language/}
\item Mercator Research Centre dossier on Faroese in the Faroe Islands. \url{https://wiki.mercator-research.eu/languages:faroese_on_the_faroe_islands_under_construction2}
\end{itemize}

\section{Religious and Community Resources}
\begin{itemize}
\item The Faroese Bible Society (Hin F{\o}royski B\'ibliugrunnurin), publisher of the Victor Danielsen translation. \url{https://biblian.fo/english}
\item Wikipedia, ``Bible translations into Faroese''. \url{https://en.wikipedia.org/wiki/Bible_translations_into_Faroese}
\end{itemize}

\section{Digital and Audio Resources}
\begin{itemize}
\item Faroese Online: list of books and resources for learning Faroese. \url{https://faroeseonline.com/resources/}
\item Faroese language course for beginners (Study in the Faroe Islands). \url{https://studyinfaroeislands.fo/life-in-the-faroes/learn-the-language/faroese-a-language-course-for-beginners}
\item University of the Faroe Islands news item on a Faroese course book for foreigners (Adams and Petersen). \url{https://www.setur.fo/fo/setrid/tidindi/fralaerubok-i-foeroyskum-fyri-utlendingar}
\end{itemize}

\section{Curriculum Development Context}
Faroese already has a native-language school system and textbook publisher, so a curriculum can build on existing N\'am materials and the Sprotin and spelling dictionaries. A 2024 study reported in the search results found a severe shortage of materials for Faroese as a second language, which is the clearest gap.

\end{document}
